    auth._fireAuthEventForTest('SIGNED_IN', { user: { id: 'u76', email: '76@example.com' }, access_token: 't', expires_at: Math.floor(Date.now() / 1000) + 3600 });
    for (let i = 0; i < 6; i++) await new Promise((r) => setTimeout(r, 0));
