  const ROW_B = { league_id: 'L-B', id: 'mB', role: 'player', display_name: 'Drew', active: true, leagues: { name: 'League B' } };
  const realFetch79 = globalThis.fetch;
  globalThis.fetch = async () => ({ ok: true, json: async () => ({ oneSignalAppId: 'test-app-id' }) });

